fn solve(a: i8, b: i8, f: i8, k: i8) -> i8 {
    let a = a as i32;
    let bcap = b as i32;
    let f = f as i32;
    let k = k as i32;

    // Basic leg lengths
    let d1 = f;       // start -> station
    let d2 = a - f;   // station -> end

    // If you can't even traverse a required leg, impossible.
    if bcap < d1 || bcap < d2 {
        return -1;
    }

    // Special-case single trip: only 0 or 1 refuel can ever be needed.
    if k == 1 {
        if bcap >= a {
            return 0; // can do whole trip without station refuel
        } else if bcap >= f {
            return 1; // must refuel once at station to finish
        } else {
            return -1; // can't even reach station
        }
    }

    // For k > 1, simulate greedily and just track whether we refueled at least once.
    let mut fuel = bcap;
    let mut used_refuel = false;

    for trip in 1..=k {
        let forward = (trip % 2) == 1; // trip 1: start->end, trip 2: end->start, ...

        // Distances before and after the station for this direction
        let first_leg = if forward { d1 } else { d2 };
        let second_leg = if forward { d2 } else { d1 };

        // Go from endpoint to station
        if fuel < first_leg {
            return -1;
        }
        fuel -= first_leg;

        // At station: decide if we must refuel.
        // Need enough fuel from station to:
        // - if last trip: reach the endpoint (second_leg)
        // - else: reach endpoint (second_leg) and then reach station again on next trip's first_leg
        let need_after_station = if trip == k {
            second_leg
        } else {
            // next trip's first leg is the opposite direction's first_leg:
            // If we are forward now, next is backward so first_leg_next = d2,
            // If we are backward now, next is forward so first_leg_next = d1.
            let first_leg_next = if forward { d2 } else { d1 };
            second_leg + first_leg_next
        };

        if fuel < need_after_station {
            // Refuel to full (only possible at station)
            fuel = bcap;
            used_refuel = true;
        }

        // From station to the other endpoint
        if fuel < second_leg {
            return -1;
        }
        fuel -= second_leg;
    }

    if used_refuel { 1 } else { 0 }
}